// docs/superpowers/plans/2026-11-01-reload-hand-poses.md Task 2 (mag rows BY MESH - plan amendment 2026-11-01 (5)).
// Exit code = number of failures.
// Compile: cl /nologo /EHsc /W4 /WX /std:c++17 /I src\src\ovr2xr src\src\tests\reload_hands_test.cpp
#include "reload_hands.h"
#include "twohand_shotgun.inc"             // kShotgunStd (twohand.cpp's table - generated by tools/twohand_shotgun.py)
#include "data/twohand_shotgun_check.inc"  // kShotgunGripCheck (the same generator's raw json reference)

#include <cmath>
#include <cstdio>
#include <cstring>
