// ---- crossbow (plan docs/superpowers/plans/2026-11-03-manual-reload-crossbow.md Task 2): Jay's RACK GRAB (blend/pose_rack_jay.json) by
// mesh, in bone_stringreload's REST LOCAL frame; the bolt CARRY fist (blend/pose_A2_jay.json) = kCarryRows, fingers only.
const char* const kXbows[] = { "wn_crossbow_f", "dlc_wn_crossbow_a", "dlc_wn_crossbow_a_upgrade_a" };

void CrossbowRackRowForEachMesh()
{
    for (const char* m : kXbows) {
        const HandRow* r = RackRowFor(Family::Crossbow, m, "crossbow");
        CHECK(r != nullptr);
        if (r) {
            CHECK(std::strcmp(r->key, m) == 0);
            // the hand sits near the rack's knob (bone_stringreload's rest frame), not at a far default
            const float d = std::sqrt(r->handT[0] * r->handT[0] + r->handT[1] * r->handT[1] + r->handT[2] * r->handT[2]);
            std::printf("  crossbow rack row %-28s |handT| %.4f m\n", m, d);
            CHECK(d > 0.0f && d < 0.25f);
            // Task 2 review I-1: the row PINNED (1e-5) to the generated values. tools/reload_hand_poses.py's independent control placed
            // Jay's l_hand in the clip-built FORWARD bone_stringreload at 6.85e-05 m / 0.0000 deg from this row; without the forward
            // shift handT.z is +0.1295 (0.218 m off), with it negated +0.3470 - both fail here.
            const float kR[9] = { 0.008742f, 0.000107f, -0.999962f, 0.038637f, 0.999253f, 0.000445f, 0.999215f, -0.038640f, 0.008731f };
            const float kT[3] = { -0.043356f, 0.033821f, -0.087934f };
            for (int i = 0; i < 9; ++i) { CHECK(Near(r->handR[i], kR[i], 1e-5f)); }
            for (int i = 0; i < 3; ++i) { CHECK(Near(r->handT[i], kT[i], 1e-5f)); }
        }
        CHECK(RackRowFor(Family::Crossbow, m, "crossbow", true) == RackRowFor(Family::Crossbow, m, "crossbow"));   // one handle
    }
    CHECK(RackRowFor(Family::Crossbow, "WN_CROSSBOW_F", "CROSSBOW") != nullptr);   // any case
    CHECK(RackRowFor(Family::Crossbow, "wn_crossbow_x", "crossbow") == nullptr);
    CHECK(RackRowFor(Family::Crossbow, nullptr, "crossbow") == nullptr);
}

void CarryRowIsFingersOnly()
{
    const HandRow* r = CarryRowFor(Family::Crossbow);
    CHECK(r != nullptr);
    if (!r) { return; }
    CHECK(std::strcmp(r->key, "crossbow_bolt") == 0);
    const float I[9] = { 1, 0, 0, 0, 1, 0, 0, 0, 1 };
    for (int i = 0; i < 9; ++i) { CHECK(r->handR[i] == I[i]); }
    for (int i = 0; i < 3; ++i) { CHECK(r->handT[i] == 0.0f); }
    int moved = 0;
    for (const FingerRow& f : r->fingers) {
        CHECK(f.name != nullptr && std::strncmp(f.name, "l_finger", 8) == 0);
        bool same = true;
        for (int i = 0; i < 9; ++i) { same = same && f.rest[i] == f.pose[i]; }
        moved += same ? 0 : 1;
    }
    CHECK(moved > 0);   // a closed fist: the fingers are not at rest
    CHECK(CarryRowFor(Family::None) == nullptr);
    CHECK(CarryRowFor(Family::Pistol) == nullptr && CarryRowFor(Family::Smg) == nullptr && CarryRowFor(Family::Rifle) == nullptr);
}

void CrossbowRowNotReachedByOtherFamilies()
{
    for (const char* m : kXbows) {
        CHECK(RackRowFor(Family::Pistol, m, "beretta") == nullptr);
        CHECK(RackRowFor(Family::Smg, m, "crossbow") == nullptr);
        const HandRow* s = RackRowFor(Family::Smg, m, "submachinegun");   // the SMG is keyed by PREFIX: its own row, never the crossbow's
        CHECK(s != nullptr && std::strcmp(s->key, "submachinegun") == 0);
        CHECK(RackRowFor(Family::Rifle, m, "m16") == nullptr);
        CHECK(RackRowFor(Family::None, m, "crossbow") == nullptr);
        CHECK(MagRowFor(Family::Crossbow, m) == nullptr);       // no magazine
        CHECK(PullRowFor(Family::Crossbow, m) == nullptr);
    }
    CHECK(RackRowFor(Family::Crossbow, "wn_rifle_a", "crossbow") == nullptr);
    CHECK(RackRowFor(Family::Crossbow, "wn_pistol_b", "crossbow") == nullptr);
    CHECK(RackRowFor(Family::Crossbow, "submachinegun", "submachinegun") == nullptr);
    CHECK(RackRowFor(Family::Crossbow, "crossbow_bolt", "crossbow") == nullptr);   // the carry row is not a rack row
}

